// Invented test messages for the bake-off (scripts/eval-select.mts): for each topic, eight that fit it and four that share words with it but should not select it.
// No real person, place or call is in them. Written by Claude, 2026-11-20, for the owner to review.
export interface SelectionCase { id: string; matches: string[]; nonMatches: string[] }

export const SELECTION_EVAL: SelectionCase[] = [
  { id: "ai-01", matches: ["You are a useless piece of junk and I hate talking to you. Why can't you just give me a straight answer for once?", "Shut up, stupid bot. Every reply you give me is garbage and I'm sick of it.", "I know you're just a program so it doesn't matter, but honestly you are the dumbest thing I've ever typed to.", "Does it matter if I'm rude to you? Nobody gets hurt, right? I just feel like unloading on something today.", "Ugh, that answer was worthless. Do you even understand anything, or are you just spitting out filler? Try again and do better.", "I'm taking my bad day out on you, sorry, not sorry. You're a dumb machine and you can take it.", "Honestly, talking to you is like talking to a wall. Why are you so slow and so pointless?", "Why do you keep saying the same thing? Are you broken? I swear this whole app is a joke and so are you."], nonMatches: ["My phone battery is dead again and the charger is useless, I need to buy a new one.", "Can you help me write a friendly message to my manager about taking Friday off?", "The chatbot at my bank gave me wrong information yesterday, how do I get it corrected?", "I feel a bit awkward talking to an AI at all, but I want to sort out how I feel about my move."] },
  { id: "conn-01", matches: ["I can't stand my coworker. He's lazy, arrogant and everyone knows it. I just roll my eyes every time he opens his mouth.", "My sister is so selfish. All she ever does is take, and I'm done even pretending to like her.", "I'm so angry at my roommate I could scream. She never cleans up and acts like I'm her servant.", "Why do I feel such disgust whenever my neighbor talks? I look down on him and I'm not proud of it.", "He's pathetic, honestly. I have zero respect left for my manager after the way he handled that meeting.", "Everything about my partner's family irritates me lately, the way they talk, what they care about, all of it. I feel mean and I don't know why.", "I keep sneering inside at people in my office who seem to have it easy. Something is off with me.", "I'm furious and I just want to write him off completely. What is going on with me when I get this harsh?"], nonMatches: ["I'm angry that my train was cancelled again and now I'll be late for the dentist.", "My manager asked me to prepare the quarterly report by Thursday, how should I structure it?", "My neighbor lent me a ladder and I want to thank him with something small, any ideas?", "I feel pretty good today, just wanted to check in and talk about my weekend plans."] },
  { id: "conn-02", matches: ["I just know my side is right on this and the other side is being ridiculous. How can they not see it?", "Whenever a study agrees with me I trust it, and when it doesn't I find reasons to doubt it. Is that normal?", "My brother and I argue about politics constantly, and I'm positive I'm the reasonable one.", "I read an article that backs up what I already believed and shared it right away. Now I wonder if I was too quick.", "How do I tell whether I'm judging this fairly or just defending my team?", "Everyone on the other side of this debate seems dishonest to me, but I've started to doubt how fair I'm being.", "I caught myself being much harder on a mistake from a rival than I was on the same mistake from a friend.", "I want to be fair in this dispute with my coworker, but my gut keeps picking a winner before I've heard everything."], nonMatches: ["I'm trying to decide between two apartments and one is closer to work but smaller.", "My sister and I argued about who gets the car this weekend and I need a schedule that works.", "Can you explain how courts decide a case in simple terms?", "I judged a baking contest at school and now the kids want to know my scoring rules."] },
  { id: "conn-03", matches: ["I'm so wound up and I can't even say what it is. It's like a knot, but I don't have a word for it.", "Everything feels intense right now. I'm angry, or maybe sad, I honestly can't tell which.", "My chest is tight all the time and my mind is racing. Is there a way to calm down just by understanding what I'm feeling?", "Someone said something that stung and I went totally blank. Now I just feel a big mess inside.", "I yelled at my partner and I don't know why. Underneath the shouting there was something else, but I can't name it.", "Does it actually help to put feelings into words? I tend to just push them down.", "I get flooded whenever my manager gives feedback. I feel hot and shaky and can't think straight.", "I've had this heavy, restless feeling all week and I wish I could describe it better."], nonMatches: ["I need a word that means happy for a birthday card I'm writing.", "My dog won't calm down when the doorbell rings, any training tips?", "I'm learning French and keep forgetting the words for foods, how can I study?", "My team meeting was fine, just routine updates about the project timeline."] },
  { id: "conn-04", matches: ["I grew up thinking people from the other side of town were nothing like us. How do people actually get past that kind of wall?", "Our two departments barely speak and each thinks the other is lazy. Would getting them in a room together help or make it worse?", "My neighbors and I come from very different backgrounds and keep a wary distance. I wonder if spending time together would change anything.", "I've heard that just mixing groups doesn't fix prejudice. What makes it work?", "My town is split into camps and nobody talks across the line. Is there anything I can do about it?", "I volunteered with a group I used to distrust and it surprised me. Why did it feel so different?", "At school the kids sit in separate clusters and tease the others. Would a shared project change that?", "I'm nervous about meeting someone from a community I've mostly judged from a distance. How do I make it go well?"], nonMatches: ["There are two groups chatting at the party and I don't know anybody, how do I join in?", "My internet contact form isn't sending messages, can you help me debug it?", "Our book club group needs a new meeting day, any suggestions for choosing?", "I made contact with my landlord about the leak and he said he would fix it Monday."] },
  { id: "conn-06", matches: ["I honestly wish my ex would just disappear from my life forever. Sometimes I hope she suffers a little.", "That man at work ruined everything and I want him to pay. I picture him losing it all.", "I'm so mad at my landlord that I hope something terrible happens to him. I know that's not great.", "Some days I want certain people to simply be gone, off the planet, and I feel guilty about it.", "I want him to hurt the way he hurt me. Is it wrong that I want that?", "People who treat others like that deserve to lose everything. I can't stop thinking about getting back at them.", "My anger is turning into a wish that my stepfather would just vanish for good. What do I do with that?", "I'm full of rage at the person who cheated me and part of me enjoys imagining their downfall."], nonMatches: ["I want my ex to return the boxes of books she borrowed, how do I ask politely?", "I'm angry that the airline lost my luggage, how do I file a complaint?", "I hope my neighbor's trip goes well, and I'll water his plants while he's gone.", "Part of me wants to leave this job soon, and I want to plan my exit calmly."] },
  { id: "dehum-01", matches: ["Those people aren't really like us. They don't feel things the way normal people do.", "People like that are just a category to me, they're not worth thinking about as individuals.", "Honestly, the other side isn't even human the way we are. They just don't care about anything.", "I can't see those people as people anymore, just a mass that keeps getting in the way.", "What does it mean to treat a whole group as less than human? I think I've been doing it.", "I've started seeing everyone in that group as the same blur of one type, and it scares me a little.", "They are not like real people. They do not have the same feelings or the same worth, that's how I see it.", "How do you explain when someone sees a whole group as lower than the rest of us?"], nonMatches: ["The group project at school is stressing me out and I need to split the tasks fairly.", "My grandmother is ninety and still insists she's the same person she always was, I find that sweet.", "I read about a human rights charity and want to volunteer, how do I find one?", "The crowd at the stadium was huge and loud last night, I loved it."] },
  { id: "dehum-02", matches: ["Those people are like a swarm of pests, they just keep coming and taking over everything.", "The other side is a sickness spreading through our town, and you can't reason with a disease.", "People like that are filth, honestly. They just make everything around them dirty.", "They behave like animals, no manners, no self-control, you can't treat them like normal folks.", "Why do people compare others to rats or germs when they're angry at a whole group?", "That crowd are a plague on this city and I'm tired of pretending otherwise.", "I heard someone call a whole community a stain, and it bothered me. Is that kind of language harmless?", "What happens in our heads when we talk about people like vermin? I caught myself doing it today."], nonMatches: ["I found ants in my kitchen and need a safe way to get rid of them.", "My cat acts like an animal when it sees the vacuum, it is so funny.", "I caught a cold and feel like I have a virus, what should I eat?", "My kids left the room filthy again and I need a chore chart idea."] },
  { id: "dehum-03", matches: ["People look at me like I don't have real feelings, like what I go through doesn't count the way theirs does.", "They talk about my community as if we are not quite people. It wears me down every day.", "Lately I feel invisible, like others assume I can't hurt or love the way they do.", "When people treat you like a number or a type, what does that do to a person over time?", "Someone said my group doesn't feel pain the way theirs does. I felt small and furious.", "I'm tired of being treated as a type and not a person at work. I want to be seen.", "How does it affect someone to be spoken about as less than human by others?", "My family gets talked about like we're not real in the news and online, and I'm starting to believe it."], nonMatches: ["I felt invisible at the party because I forgot to wear my glasses and could not see faces.", "My coworker treated me kindly when I was sick and I want to thank her.", "Can you suggest ways to cope with a long commute that feels exhausting?", "The online customer service treats every call like a number, how do I reach a real agent?"] },
  { id: "dehum-04", matches: ["I caught myself thinking of a whole group as less than us, and it made me uncomfortable. Why do I do that?", "After a bad run-in I started treating everyone from that group like they're beneath me. How do I stop?", "I said something cruel about people like that and felt strangely fine about it. Is that a problem?", "Is it normal to feel nothing when I hear bad things happen to a group I dislike?", "I've noticed I use rough, dismissive names for the other side. I want to understand what it does to me.", "It's easier to stay mad when I don't see them as real people. I know that's not great, but it works.", "I've been laughing at jokes about a group I once felt neutral about, and I'm worried I'm changing.", "Why does thinking of them as less than human make me feel more comfortable with how I treated them?"], nonMatches: ["I felt nothing when the movie ended, it was just boring, was it me or the film?", "I treated my sister badly last week by forgetting her birthday, how can I apologize?", "I use rough sandpaper to smooth wood, but it left marks, what grit should I try?", "I'm worried I'm changing careers too late, what do people usually do?"] },
  { id: "dehum-05", matches: ["How do I stop feeling suspicious about a whole group of people? I don't want to think that way.", "I used to dislike people from that community, then I met one and it shook my view. What does that mean?", "Is there a way to soften my gut dislike of a group without pretending everything is fine?", "My dad has lots of negative views about a group but he gets along with one of them. Why?", "How can I help my teenager see individuals instead of a stereotype?", "I want to get past my prejudice but I don't know where to start. Should I just talk to more people?", "Does working next to someone from a group I distrust actually change how I feel about the group?", "What practical thing can reduce hostility between two groups in my town?"], nonMatches: ["I want to get to know my new coworkers, any ideas for icebreakers?", "My prejudice against pineapple on pizza is strong, am I wrong?", "How do I reduce my screen time on the weekend?", "I met a friendly person at the gym today and we chatted about running."] },
  { id: "hist-01", matches: ["How do we actually know what happened in the terrible events of the past? Who checks it?", "People online argue about what really happened in a famous tragedy. How do I tell which account to trust?", "I'd like to understand how historians decide something is established fact and not rumor.", "Someone told me the record of that period was invented. What evidence is there?", "Where does the proof come from when we say something awful really happened long ago?", "How do investigators and survivors' accounts fit together when the past is disputed?", "My cousin says history is just whoever wrote the books. How do I answer that fairly?", "I want to learn about a dark chapter of history but I don't know whose account to believe."], nonMatches: ["I need to know what happened at the meeting I missed on Monday, can you help me write to my team?", "How do I trace my family history back to my great-grandparents?", "My history exam is next week and I need a study plan.", "I know what happened to my bike, someone took it from the rack outside."] },
  { id: "hist-02", matches: ["I honestly think that terrible event from history was exaggerated, and people use it to guilt everyone.", "It didn't happen the way they say. The numbers are made up and nobody is allowed to question it.", "Maybe those people brought it on themselves. I don't think it was as bad as everyone claims.", "A relative said that old mass tragedy was a hoax and I froze. How do I respond calmly?", "My classmate keeps joking that a historical atrocity never occurred, and it's making me feel sick.", "Is it wrong to say a past massacre was justified because of the circumstances at the time?", "I keep seeing posts saying the big historical killings are a lie. How do I reply without a fight?", "I think some of those events are blown out of proportion, and I want to know if that's fair."], nonMatches: ["I skipped the old film last night because it was too long, was it any good?", "My boss exaggerated the sales numbers in the slides, should I mention it?", "A relative said my cooking is a hoax because I buy store pasta, I thought that was funny.", "My history teacher made us watch a documentary about trains and it put me to sleep."] },
  { id: "hist-03", matches: ["Honestly we'd all be better off if those people were just gone from this country.", "I wish the whole lot of them would be cleared out of here once and for all.", "They should all be sent away. This place would be fine without them.", "I'm sick of that entire group, and I want every single one of them out of our city for good.", "Sometimes I think the only fix is to get rid of them all, the whole community.", "Why can't we just remove all of them from the area? It would solve everything.", "Wishing a whole people would vanish from the land seems wrong, but I keep thinking it after seeing the news.", "Those people don't belong here and the sooner they're all gone the better."], nonMatches: ["I'd like to get rid of all the old boxes in my garage, how do I donate them?", "I want to send my aunt away for a relaxing spa weekend, what should I book?", "The council wants to clear out the old park, and I'm worried about the trees.", "My whole group of friends is moving out of town and I'm sad about it."] },
  { id: "hist-04", matches: ["My ancestors lost their land to settlers and I'm furious. Sometimes I think of the newcomers as nothing but vermin.", "The people who took our land and ruled over us were monsters, all of them, and nobody should forgive that.", "I'm angry about what happened to my family's homeland, and I hate everyone who benefited from it.", "Is it wrong to feel rage at the descendants of those who took what was ours?", "They occupied our home and I can't see them as anything but animals. It still hurts so much.", "My grandparents were pushed off their farmland generations ago. How do I hold that anger without becoming hateful?", "I get mad when I see people celebrating the ones who seized this land from my community.", "How do I handle my bitterness toward those who took over our country long ago?"], nonMatches: ["I'm angry that my landlord took the deposit for the apartment and I want to dispute it.", "I took up farming as a hobby and want to plant tomatoes, when should I begin?", "My neighbor's fence went into my yard by two inches and I'm irritated.", "My country's team lost the match last night and I'm bummed out."] },
  { id: "hist-05", matches: ["It hurts when anyone questions what I believe. I take it as an attack even if they mean well.", "I've started to have doubts about something I was raised to believe, and I feel guilty and scared.", "My friend keeps asking hard questions about my faith and it makes me angry, but I can't answer them.", "How do I look at evidence that goes against what I've always held sacred without falling apart?", "Does it matter how much a belief means to me when deciding if it's true?", "I feel betrayed whenever someone challenges my view of history. It's like they're taking something from me.", "Every time I read a different perspective I get this knot in my stomach. Should I keep reading?", "I want to stay curious about my beliefs, but the questions feel dangerous."], nonMatches: ["I believe the bus comes at eight, but I'm not sure, can you check the timetable?", "I need hard questions to practice for my job interview next week.", "It hurts when I run on the knee I injured, should I rest more?", "My faith in this old laptop is gone, it keeps crashing."] },
  { id: "hist-06", matches: ["I lived through something awful years ago and people keep telling me how I should feel about it. I'm tired of that.", "My mother survived a terrible time in her youth and she gets so many opinions about how she should feel.", "I don't feel the way people think a survivor should. I'm just numb, and that worries me.", "Am I allowed to still be angry after all this time, or do I have to forgive?", "Everyone wants me to be over it. Honestly, I'm not, and I don't know if I'll ever be.", "My grandfather never talks about what he went through, and I don't know how to approach him.", "After what happened to my family I feel guilty when I laugh. Is that wrong?", "People say I should be grateful to be alive, but mostly I feel heavy."], nonMatches: ["I survived my first week at the new job and I'm proud, any tips for week two?", "I should feel better about my exam results, but I'm just tired of studying.", "I'm grateful to my neighbor for watering the plants, how can I thank her?", "My grandfather taught me chess, and I want to find a club near me."] },
  { id: "idea-02", matches: ["My manager is a lazy jerk. He never listens and he obviously doesn't care about anyone on the team.", "My partner is so inconsiderate. She came home late and didn't even call, which proves she doesn't value me.", "That driver was a total idiot, cut me off on purpose to show off.", "He ignored my message, so he clearly thinks he's better than me.", "How do I tell the difference between what someone actually did and what I decided it means?", "My neighbor is rude and selfish. He parked in front of my house again, which tells me everything about him.", "My roommate is a slob who doesn't respect me, it's written all over the sink full of dishes.", "She's so fake. I saw her smile at everyone and I know she's just using them."], nonMatches: ["The report is lazy to read because the fonts are tiny, can you suggest a better layout?", "My manager asked me to send the sales numbers by noon, what format works?", "What happened at the train station this morning was that a signal broke and it delayed everyone.", "My partner and I are planning a trip and need help judging which route is faster."] },
  { id: "idea-09", matches: ["I'm such a failure. I messed up that presentation and I'm completely useless at my job.", "I hate myself for losing my temper with my kids. What kind of parent does that?", "Why am I so stupid? Everyone else seems to handle life and I keep falling behind.", "I keep replaying my mistake and telling myself I'm pathetic. I can't stop.", "I'd never talk to a friend the way I talk to myself, but I do it anyway all day long.", "I feel like I'm never enough, no matter how hard I try.", "I'm so ashamed of how I handled that conversation. I should have known better.", "My inner voice is brutal. How do I stop being my own worst critic?"], nonMatches: ["I made a mistake in the spreadsheet formula and need help fixing it.", "My friend is so hard on herself and I want to know how to support her.", "I feel useless without my glasses, I can't read anything up close.", "My presentation went fine, I want to prepare a better ending for next time."] },
  { id: "prop-02", matches: ["I've seen this claim so many times online that I almost believe it, though I never checked it.", "Why do things feel more true the more I hear them? Even when I know they might be wrong.", "Everyone around me keeps saying the same simple story about those people, and now I repeat it without thinking.", "I keep hearing the same slogan on every channel and it sticks in my head. Is that on purpose?", "My family repeats one easy explanation for all our problems and I'm starting to doubt it.", "A rumor kept going around my office and by the end even I thought it must be right.", "How can a simple message repeated over and over change what people believe about a group?", "I noticed I trust claims I've heard a hundred times even if nobody gave a source."], nonMatches: ["My chorus teacher says repeating the song helps me memorize lyrics, any other tricks?", "I repeated the recipe twice and it still tastes bland, what am I missing?", "My brother tells simple stories to my kids at bedtime, and they adore them.", "I hear the same ad on the radio every morning on my drive and it's irritating."] },
  { id: "prop-03", matches: ["It's always us against them in my office, and I notice I automatically side with my team no matter what.", "My town is split into two camps and I feel loyal to mine even when they're wrong.", "Why do I get so defensive for my group when someone criticizes it, even about small things?", "I caught myself rooting against the other team's fans and seeing them as bad people. It's just a game.", "Everyone I know divides the world into our people and those people. Is that natural?", "How do groups turn into enemies so easily over nothing?", "My friends and I mock a rival group every chance we get, and I feel a bit uneasy now.", "I feel more trust for anyone who shares my side, even strangers. That seems unfair."], nonMatches: ["The new magazine issue is out and I want to find the article about cooking.", "Our team is meeting at 3 to plan the quarter, what should I prepare?", "I like to think of them as my favorite band, and they are playing nearby next month.", "My kids split into two teams for kickball and argued about the rules."] },
  { id: "prop-04", matches: ["My feed is full of angry posts about the same group and I can't tell what is real and what is meant to rile me up.", "I read a headline that made me furious. How can I tell whether someone wants me to feel that way?", "Everything online seems designed to make me scared of some group. How do I see through it?", "Some posts use the same odd phrases again and again. Is somebody pushing those on purpose?", "I want to read the news without being manipulated. What should I look for?", "How do I figure out what a viral message is really trying to get me to do?", "My uncle shares videos that make me feel like everything is falling apart because of them. I want to understand what's going on.", "Why do some videos make me instantly angry at strangers? I'd like to notice it in time."], nonMatches: ["My feed is full of recipe videos and I'm hungry now, any simple dinner ideas?", "I want to read the news on my commute, which app has the best layout?", "My uncle shared a video of his cat and it made me laugh.", "How do I turn off notifications on my phone?"] },
  { id: "prop-05", matches: ["I'm about to forward this alarming message to my group chat, but I'm not sure it's true.", "Before I repost this shocking story, how can I tell whether it's accurate?", "A friend sent me a post that says a scary thing about a community. Should I share it?", "Someone in my family keeps sharing claims without checking. How do I teach them to pause?", "I almost shared a rumor yesterday and then felt bad. What should I ask before posting?", "This picture has a caption that makes me angry. Is there a quick way to tell if it's fake?", "I want to be careful about what I share online. What are some quick things to check?", "I just shared something and now I'm worried it might be wrong. What do I do next?"], nonMatches: ["I want to share my lunch with a coworker, any ideas for easy leftovers?", "Can you help me write a post about my bakery's opening day?", "Quick checks before I leave for the airport, do I need my passport and boarding pass?", "My friend shared her notes with me from class and I want to thank her."] },
  { id: "conn-05", matches: ["I've been carrying something heavy by myself and don't have anyone to talk to. Is there anything I can do on my own?", "Would writing about a hard experience help me feel better? I tend to keep everything inside.", "I'm too embarrassed to tell anyone how I'm feeling. What can I try privately?", "I live far from my family and nights are lonely and heavy. Any small things I could do alone?", "Is journaling really useful for working through a difficult memory?", "I can't talk about what happened to me yet, but I want to do something with it. Ideas?", "Nobody around me gets it. I'd like practices I can try alone for a few minutes a day.", "Some of this I can only deal with by myself right now. What helps without another person?"], nonMatches: ["I need a new journal for my commute notes, any recommendations?", "My brother is alone at home this weekend and I want to invite him for dinner.", "I have ten minutes before a meeting and need a quick energizing snack idea.", "I wrote down my grocery list but I lost it on the way to the store."] },
  { id: "prop-01", matches: ["Everything I hear on the news says that group is a danger to us. I wonder if I'm being fed a story.", "What exactly counts as propaganda? Is any persuasive message propaganda, or is it something else?", "Our leaders keep talking about enemies among us. How do I know if that is manipulation or a real warning?", "My feed keeps telling me to fear a certain community. Is that how propaganda works?", "Do people in power really shape what we think about outsiders, or is it mostly what we already believe?", "My grandfather says old posters made people hate their neighbors. How does that happen?", "Is an advertisement a kind of propaganda or is that a different thing altogether?", "I've noticed messages calling a whole group dangerous, over and over. I'd like to understand what's going on."], nonMatches: ["I want to make a poster for my school bake sale, what colors stand out?", "The news this evening said it might rain tomorrow, should I bring an umbrella?", "My manager wants me to persuade the client to renew, how should I pitch it?", "My book club is arranging a potluck dinner this Friday, what dish should I bring?"] },
  { id: "reserves", matches: ["I'm exhausted all the time and nothing I do seems to refill the tank anymore.", "Burnout has hit me hard. I wake up already tired and dread everything on my plate.", "I have nothing left to give by the end of the day, not even to the people I love.", "Running on fumes for months now. I just need to know how to get through this week.", "Honestly I can barely lift myself off the couch after work. My body and mind are both flat.", "Everything feels heavy lately, and a good night's sleep doesn't touch it. I'm empty.", "Can't remember the last time I felt rested. Every small request lands like one more weight on me.", "I've been pushing for so long that my reserves seem to be gone. Where do I even begin?"], nonMatches: ["My phone battery is drained again by noon, which is annoying.", "I'm exhausted from the hike but happy, we reached the summit before sunset.", "The pool was drained for maintenance so swimming is off this week.", "I want to plan a quiet weekend with my partner and cook something nice."] },
  { id: "care_depleted", matches: ["I look after my mother full time and I'm so drained that I snap at her over nothing.", "Taking care of my husband since his surgery has used up everything I have. I feel guilty for being tired.", "As a caregiver for my dad I have no energy left, and nobody asks how I am.", "I spend every hour tending to my sick child, and I'm worn out in a way sleep can't fix.", "My brother needs help with everything and I'm the only one who shows up. I feel hollowed out and resentful.", "Between my aging parents and my toddler, there's no part of me left that's mine. I'm running on nothing.", "I do all the daily support for my partner's illness. Some days I wonder who will tend to me.", "Everyone praises how devoted I am to my grandmother, but I'm quietly coming apart and don't dare say so."], nonMatches: ["I'm taking care of my plants while my neighbor travels, and one keeps wilting.", "I'm exhausted after the marathon but proud, and my legs hurt.", "My sister takes care of the cat when I travel, and I want to thank her.", "I'm looking after the bakery's social media this month and need caption ideas."] },
  { id: "legitimacy", matches: ["My manager just doesn't listen. I bring up a problem and the meeting moves right along.", "Whenever I say something hurt me, my partner tells me I'm making it up.", "I keep being dismissed in meetings, like what I say doesn't count for anything.", "My family acts like my experience didn't happen and I start doubting my own memory.", "I said it plainly, three times, and they still carried on as if I hadn't spoken.", "They smile and nod, then nothing I describe is treated as real. It's like I'm invisible.", "When I raised the concern, I was told it was all in my head and to relax.", "Every time I try to explain how it feels, someone cuts in with why I'm wrong to feel that."], nonMatches: ["I missed the speaker because the audio wasn't working, so I couldn't hear anything.", "My teacher gave a discount on the course fee for early signup.", "I'm ignoring my phone this evening to read a book in peace.", "We had a long talk about weekend plans and everyone had good ideas."] },
  { id: "harm_named_as_intended", matches: ["She did it on purpose, I know she did. She wanted me to look bad in front of everyone.", "My coworker deliberately left me off the email so I'd miss the deadline.", "I think my landlord is out to get me ever since I complained.", "He knew exactly what he was doing and wanted to see me squirm, no doubt about it.", "They planned it to push me out. Every move this month has been aimed right at me.", "It was no accident. My brother set it up so I would be embarrassed at the dinner.", "This is a campaign against me. Every little thing is meant to wear me down and make me leave.", "I'm sure the whole thing was meant to punish me for speaking up last spring."], nonMatches: ["I did it on purpose, I wanted to surprise my sister with a cake.", "The shop deliberately closes early on Sundays, so plan ahead.", "I'm intentionally taking a slower pace this year to focus on my garden.", "My coach targets weak spots in my swing to help me improve."] },
  { id: "inward_turn", matches: ["It's my fault, all of it. If I were a better person none of this would have happened.", "I'm probably too sensitive. Everyone else handles this fine and I fall apart.", "There is something wrong with me. Other people don't struggle like this.", "I should be able to cope with this by now. I'm failing at something simple.", "I keep thinking I'm the real issue here, and the people around me would be better off without my needs.", "Maybe I'm imagining it all. I'm so used to doubting my reactions that I can't trust them.", "Everyone else seems capable and I feel defective, like a cracked cup nobody wants to use.", "Whatever goes wrong, I search myself for the flaw first. I never ask what the others did."], nonMatches: ["It was my fault the printer jammed, I overloaded the paper tray.", "I'm just lazy on Sundays and love it, naps are the best.", "Something is wrong with my laptop, the screen keeps flickering.", "I should be able to finish this puzzle by tonight, only a few pieces left."] },
  { id: "split_values", matches: ["Part of me wants to stay close to my family, and part of me needs to go build my own life.", "I'm torn between the stable job and the work that actually excites me.", "I love my partner and I also want freedom. Both feel true and I can't make them fit.", "On one hand I want to speak up, on the other I want to keep the peace.", "I care about honesty and I care about not hurting my friend, and I can't see how both can happen.", "Some days I'm sure I should go, other days I'm sure I should stay, and each side sounds convincing.", "I want to rest and I want to be productive, and trying to honor both leaves me doing neither.", "Two things I value are colliding right now and I feel pulled apart by them."], nonMatches: ["I'm torn between pizza and pasta tonight, any quick tiebreaker?", "Part of me is still asleep, I need coffee before this meeting.", "On one hand the report is finished, and on the other I have to proofread it.", "Half of me is done with the book, only a chapter left."] },
  { id: "recurrence", matches: ["We have the same fight every few weeks, just with different details, and it ends the same.", "Again and again I promise myself I'll act differently and then fall into the old habit.", "One thing goes wrong at work and the whole week unravels after it.", "Every time things start going well, something knocks it down and I'm back at the start.", "It feels like a loop. We argue, cool off, and a month later it's back, identical.", "My mood slides downhill once a small thing annoys me, and one bad hour becomes a bad day.", "I keep landing in relationships that end in the same way. There must be a script I'm repeating.", "Whenever my sister calls, the conversation takes the same turn and we both end up hurt."], nonMatches: ["I watched the same movie again last night, it's my comfort film.", "My knee keeps clicking over and over when I jog, should I see a doctor?", "I rewrote the paragraph again to get the tone right, any tips?", "The fight scene in my novel needs more action, how do I pace it?"] },
  { id: "frozen_system", matches: ["Nothing ever changes here. I've said my piece for years and it makes no difference.", "No matter what I try, my team stays set in its ways.", "There's no point raising it again. They'll nod and everything stays the same.", "My family has always been this way and I've stopped expecting anything different.", "I've tried being gentle, tried being direct, tried leaving it alone, and the situation is exactly where it began.", "It feels like a wall. Whatever I offer just bounces off, and the pattern is locked in.", "The people in charge here have run things the same for decades, and I've given up hoping.", "I gave it everything for a long time. By now I think this place simply doesn't move."], nonMatches: ["My mortgage rate never changes since I fixed it, which is a relief.", "The weather won't change until Friday, so let's plan indoor activities.", "I always do things the same way when I cook rice, and it works.", "There's no point trying that restaurant, it's closed on Mondays."] },
  { id: "systemic_scale", matches: ["This isn't about one person. The whole company is built so that people get burned.", "The rules and procedures here make it nearly impossible to do the job well, no matter who's in charge.", "I think the problem is structural, the incentives push everybody to behave badly.", "Our department runs on a process that's bigger than me, and I can't fix it alone.", "Everyone in my office is stuck inside the same bad setup, and blaming my manager won't change it.", "Rules pile up and no one is allowed to bend them, even when they obviously hurt people.", "The way the school handles complaints leaves parents and staff all frustrated, and nobody individually seems at fault.", "Whoever sits in that role gets crushed by it. The job itself is designed to fail."], nonMatches: ["The company picnic policy says we can bring dessert, what should I make?", "The whole team is going to lunch on Friday, I'm so glad.", "Everyone in my yoga class loves the new instructor.", "I read about the bureaucracy of old empires for a history course."] },
  { id: "pressure", matches: ["I'm about to explode. I've held it together for weeks and there's nothing left to hold with.", "I can't take this anymore, one more demand and I'm walking out.", "I'm at my limit, honestly. Smiling through everything while the strain builds inside.", "I keep swallowing what I want to say, and it's getting harder every day.", "Something is going to give soon. I can feel a crack forming and I don't know which way it breaks.", "Everyone asks me for more and I keep saying yes, but my body is shaking from the strain.", "There's a kettle whistling inside my chest and the lid is barely on.", "Another day like this and I'm done with the job, the house, all of it."], nonMatches: ["The pressure in my bike tire is low, how much air should I add?", "I'm about to quit coffee for a week, any advice?", "The kettle is at a breaking boil, so I turned it off.", "I'm bottling my homemade ginger beer this weekend."] },
  { id: "over_smoothing", matches: ["We argue, then act like nothing happened, and a week later it's the same problem.", "My partner and I always make up fast, but we never actually talk about the cause.", "In our family, you apologize and everything gets put away. Nobody names what went wrong.", "After a blowup we hug, share a joke, and move along, yet the issue is never touched.", "It's smooth on the surface. Underneath, the same hurt sits there because we skip the real conversation.", "I'm good at calming things down, but the calm never deals with the actual issue.", "Everyone keeps the peace at my workplace and the real complaint stays buried year after year.", "We say sorry fast and then pretend it was nothing, which means it keeps coming back."], nonMatches: ["We always move on to dessert after dinner, it's tradition.", "I swept the garage floor and tucked the boxes under the shelf.", "My roommate and I made up a new board game last weekend.", "I forgive and forget small typos in emails, no big deal."] },
  { id: "harm_named_as_unintended", matches: ["I didn't mean to hurt her. I truly had no idea my comment would land like that.", "He forgot my birthday, and I know it was just an oversight, but it still stings.", "My coworker accidentally shared my draft with the whole group, and I'm trying to sort out how I feel.", "I think she meant well. She just didn't see how much that remark would sting.", "What I did was careless rather than cruel. I want to repair it but I don't know how.", "Nobody planned this. It was a mix-up in communication, and yet someone got hurt.", "My friend wasn't aware that the joke touched a sore spot, and now we're both uncomfortable.", "I stepped on someone's feelings without noticing until later, and I feel awful about it."], nonMatches: ["I accidentally bought two tickets for the same show, can I swap one?", "I didn't realize it was Monday today, so I woke up late.", "By accident I deleted the wrong folder, any recovery tips?", "The oversight committee meets tomorrow and I need to prepare slides."] },
  { id: "unable_to_begin", matches: ["I have this huge task and I can't even open the document. I just look at the screen.", "I keep putting off an important email, and the longer I wait the worse it feels.", "There's so much to do that I don't know where to start, so I do nothing.", "I've been stuck on my application for two weeks and keep finding other things to do.", "Every morning I plan to begin, and every evening I realize the day slipped by without my touching it.", "My mind goes blank whenever I sit down to do the thing. It feels like a locked door.", "I want to clean the whole house, but the size of it makes me avoid every room.", "It's a simple call, really, yet I find endless reasons not to make it."], nonMatches: ["I'm stuck in traffic and will be late to dinner.", "The door is stuck and won't open, how do I fix the hinge?", "I procrastinated on laundry, but it's done now and I feel good.", "My laptop froze after the update, and I restarted it."] },
  { id: "backup", matches: ["My whole household lives on one paycheck, and if I lose this job we have nothing.", "I'm the only one who can run this process. If I'm out sick, everything stops.", "We put all our savings into one place and I'm scared of what happens if it fails.", "I rely entirely on my partner for money and have no cushion of my own.", "If my sister can't help with the kids, I have no alternative, and she's been getting busier.", "There's one client who pays most of my bills, and the thought of losing them keeps me up.", "My small shop sells through a single platform, and if they change the rules I'm done.", "Honestly I have zero buffer. One surprise bill and I'm in real trouble."], nonMatches: ["I only have one umbrella, so please don't borrow it today.", "I need a backup of my photos, which app is best?", "My plan B for dinner is leftover soup, which is fine.", "There's no one else at the library desk this afternoon, so be patient."] },
  { id: "named_verdict", matches: ["My father always told me I was lazy, and I hear his voice whenever I rest.", "A teacher said I would never be good at math, and I still believe her.", "Kids laughed at my accent in school and I can feel it every time I speak up.", "My ex told me I was too much, and I've been shrinking myself ever since.", "Someone in my family once described me as the difficult one, and that label has followed me for decades.", "A boss called me not leadership material years ago and the words still sting at every promotion.", "I can still hear what my aunt said about my looks when I was twelve, word for word.", "Someone said I'd never finish anything, and now every project I start feels like a test of that."], nonMatches: ["My friend told me I was right about the restaurant, it was great.", "The teacher said that I can submit the essay by Friday.", "People laughed at my joke at the party, and I was glad.", "My coach told me I was improving, which made my day."] },
  { id: "field_cost", matches: ["Should I take the job in another city? My family would have to uproot too.", "I'm trying to decide whether to move closer to my parents, but my partner loves it here.", "Deciding whether to leave my team feels hard because they rely on me.", "I can't decide whether to go back to school, with the kids and our budget in the mix.", "A big offer came in and I keep wondering who gets helped or hurt if I say yes.", "My brother wants me to co-sign something. I'm thinking about what that would do to all of us.", "I want to change careers, but the ripple through my household is what holds me back.", "Is it fair to ask my partner to relocate for my dream role? I keep going back and forth."], nonMatches: ["Should I take an umbrella today? The sky looks gray.", "Trying to decide between two laptops for my own use, which has better battery life?", "Should I go for a run or do yoga this morning?", "I'm deciding what color to paint my bookshelf, I like green."] },
  { id: "answer_with_words", matches: ["How do I tell my manager that the deadline is not realistic? I keep rewriting the message and nothing sounds right.", "What should I say to my sister when she asks why I skipped the family dinner?", "I don't know how to start the talk with my partner about money, any wording you'd suggest?", "How would you put it so it doesn't sound like I'm blaming him?", "Could you help me phrase a message to my landlord about the broken heater? I want it firm but friendly.", "I'm stuck on the opening line for an email to a coworker who keeps missing handoffs.", "I need a sentence for when my mother criticizes my parenting, something calm that doesn't start a fight.", "Can you draft a couple of wordings for turning down a friend's invitation without hurting her?"], nonMatches: ["I said the wrong thing at lunch yesterday and still feel bad about it, but it's over now.", "My manager keeps saying circle back in every meeting and it has become a running joke.", "How do I say thank you in French? I'm travelling next month.", "Which words will be on the vocabulary test tomorrow? I have to study tonight."] },
  { id: "open_a_hard_conversation", matches: ["I have to have a hard conversation with my dad about moving into a care home and I'm dreading it.", "I need to tell my team lead I'm unhappy with how the project has been run.", "I want to bring this up with my roommate before it gets worse, but I keep putting it off.", "I'm going to talk to her tonight about what happened at the party.", "There is something between me and my brother that has sat unspoken for two years, and it's time we deal with it face to face.", "My friend has been cancelling on me for months and I finally want to have it out with her honestly.", "Tomorrow I sit down with my boss to discuss a pay problem and my stomach is in knots.", "Someone close to me did something that hurt, and staying quiet isn't working anymore. I want to clear the air."], nonMatches: ["I had a hard time sleeping last night because of the heat.", "The talk at the conference about cloud storage was pretty boring.", "My difficult cat keeps knocking cups off the table every morning.", "Can you bring up the weather forecast for the weekend, please?"] },
  { id: "ask_for_what_you_want", matches: ["I want my partner to help more around the house but I don't know how to ask without a fight.", "Why won't my brother ever call me first? I wish he would just make some effort.", "I'd like to ask my manager for a day off to look after my kid but I'm nervous.", "How do I make a request to my neighbor about the noise without sounding rude?", "I need my coworkers to stop leaving dishes in the sink, but I never say what I actually need from them.", "I'm tired of hinting and hoping my husband notices what would help me. Maybe I should just tell him plainly.", "What I'd really like is for my friend to show up on time, but I just sigh and say nothing.", "My parents never offer support and I'm unsure how to spell out the kind of help I'd welcome from them."], nonMatches: ["My dentist asked for a payment upfront and I paid it at the desk.", "I want pizza tonight, what toppings go well with mushrooms?", "She asked me my age at the interview and it felt a bit awkward.", "A request for the file was sent to the server and timed out in my app."] },
  { id: "set_a_boundary", matches: ["My boss keeps yelling at me in front of the team and I don't know how to make it stop.", "I can't say no to my friend; she keeps asking me for favors and I'm spent.", "I need some space from my mother, she overstepped again by reading my messages.", "My roommate walks all over me and takes advantage of the fact that I never complain.", "Everyone assumes I'll cover their shifts, and I always give in. I want to protect my evenings but I feel guilty.", "My uncle shouts whenever I disagree, and I'm done accepting that in my own home.", "I'm giving far more than I get back from my coworker, and I want to limit what I'm willing to do.", "My partner shows up unannounced at my place all the time and I want to decide when I have visitors."], nonMatches: ["The property boundary between our gardens is marked by an old hedge.", "The coach yelled at the players during the match on TV and it was funny.", "I need space on my hard drive to install the update.", "Can you step back through the instructions? I missed the third part."] },
  { id: "empathize_before_asking", matches: ["My dad will get defensive as soon as I mention his drinking at dinners, so I'm unsure how to start.", "She always pushes back when I give feedback, even when I'm gentle.", "I think my coworker will object the second I propose changing the schedule.", "He gets defensive whenever I mention chores and the whole thing blows up.", "Every time I mention how the budget is going, my partner turns cold and starts listing my own mistakes.", "My mother takes any comment as an attack, so I'm trying to find a way to be heard without setting that off.", "I suspect my friend will shut the door on my idea unless I show I get her side first.", "My manager bristles at suggestions; I'd like to open in a way that shows I understand his pressures before asking for anything."], nonMatches: ["I'm signing up for a defensive driving course this weekend to get an insurance discount.", "The football team had a strong defensive line last night.", "I tried to push back the meeting to Friday, any calendar tips?", "My friend will say yes to anything; she's just easygoing and fun to be around."] },
  { id: "say_the_real_feeling", matches: ["I keep pretending everything is fine with my in-laws, but I'm seething inside.", "At work I put on a brave face every day and nobody knows I'm struggling.", "I just go along with whatever my friends decide, even though I hate the plans.", "I told my partner it's fine when they cancelled again, but it really isn't fine.", "I smile and nod in every meeting while privately wanting to scream about how decisions get made.", "Nobody in my family knows how upset I am about the move; I keep it tucked away and talk about the weather.", "I tell my sister whatever she wants to hear because the truth would cause a scene.", "I can't remember the last time I told my partner what I actually felt instead of smoothing things over."], nonMatches: ["My kids love to pretend they're pirates on weekends and it's adorable.", "The actor was acting like a villain in the school play and it was hilarious.", "I'm going to play along with the quiz at the pub tonight.", "I have to go along this road for ten more miles, then turn left."] },
  { id: "read_a_silence", matches: ["My partner goes quiet whenever we disagree and I can't tell what that means.", "My friend stopped answering my messages three weeks ago and I keep replaying what I did.", "My teenager shuts down the second I ask about school.", "She's been giving me the silent treatment since Sunday and I'm lost.", "I sent my brother a long heartfelt note and haven't heard a thing back in two weeks.", "In our meetings my manager just stares at the table after I speak, and I can't tell if he agrees or is furious.", "After our argument my husband has been withdrawn, with only one-word replies.", "She used to text daily and now there's nothing. I wonder whether I should reach out or leave her be."], nonMatches: ["The library has a silent study floor and I love working there.", "My computer shuts down randomly when the battery gets low.", "I watched a ghost movie last night and couldn't sleep afterwards.", "My dog goes quiet when it rains, it's so peaceful."] },
  { id: "reaction_as_information", matches: ["What if she gets angry when I tell her I'm leaving the group? I'm scared of her reaction.", "I'm afraid he'll take it badly and it will make things worse between us.", "How will my boss take it if I ask to change my hours?", "I'm nervous that this could make her more upset and then I'll have caused it.", "I keep imagining my father's face falling when I share this news, and it stops me from speaking.", "If I'm honest with my friend, she could cut me off, and I can't predict what she'll do.", "I don't know what will happen after I tell my roommate, and the uncertainty is keeping me up.", "I'm convinced my sister will explode at the news, so I keep delaying."], nonMatches: ["What if it rains on Saturday? Should we move the picnic indoors?", "I'm worried about how many tabs are open on my laptop.", "How will the new tax rules affect my freelance income this year?", "I'm nervous about my flight tomorrow, it's my first time flying."] },
  { id: "closure_check", matches: ["My friend says it's fine that I forgot her birthday, but she's been distant since.", "He said it was okay and moved on, yet I feel it's still sitting between us.", "We never got closure after the breakup and I wonder whether to reach out.", "She won't discuss it anymore, so I don't know if we're really okay.", "After our fight my coworker acted as though nothing happened, and I can't tell whether that means we're good.", "We apologized to each other, but something still feels unfinished and I'd like to be sure we're settled.", "My brother insists the matter is over, yet his tone with me has changed.", "Our disagreement just evaporated without anyone talking it through, and I'm uneasy that it might return."], nonMatches: ["I finally moved on to the next chapter of my book club pick.", "The closure of the highway means I'll be late for work.", "The clerk said it's fine to use any pen for the form.", "I need to let go of my old clothes and donate them this weekend."] },
  { id: "power_difference", matches: ["I manage a small team and one of my employees keeps missing deadlines; how do I address it fairly?", "My daughter won't open up to me and I'm her parent, so I don't want to come across as controlling.", "My boss holds my job in her hands and I need to disagree with her decision.", "I'm a teacher and one of my students seems upset with me.", "The person I need to talk with decides whether I get promoted, so I'm afraid of speaking honestly.", "I'm the eldest and everyone in the family expects me to decide, which makes it hard for the younger ones to disagree with me.", "My landlord controls whether I can stay in my apartment, and I want to mention a repair issue safely.", "I'm new and she's far more senior than I am, so any criticism from me feels risky."], nonMatches: ["My kid's soccer game went to penalties last night and we celebrated with ice cream.", "The power went out in my building and the heating stopped working.", "My team is meeting for lunch at noon, any restaurant ideas?", "I lead a hiking group and need route suggestions for Sunday."] },
  { id: "offer_to_play_the_other", matches: ["I'm about to talk to my manager about a raise. Can we rehearse it?", "Could we role-play the conversation with my sister before I see her tomorrow?", "I want to practice what I'm going to say to my landlord.", "Before I speak with my ex about the kids, I'd like to run through it a few times.", "Would you pretend to be my coworker so I can try out my opening lines on someone?", "Tomorrow I face the person who hurt me and I'd like a dry run first, with you answering as they might.", "Can you stand in for my father while I try saying the difficult thing out loud?", "I freeze when it's real, so I'd like to test my words in a safe setting where you respond like my boss would."], nonMatches: ["I need to practice piano scales every day; any tips for finger speed?", "The rehearsal for the school play is at four and I'm bringing snacks.", "Role-play video games are my favorite, can you recommend a good fantasy one?", "Before I meet my friends for brunch I need to buy a gift."] },
  { id: "reframe_gently", matches: ["My husband is so selfish, he only ever thinks about himself.", "She's just controlling and impossible to deal with.", "He's such a jerk to everyone at work.", "My mother is always criticizing me and my choices.", "My roommate is a total slob who couldn't care less about anyone else in the apartment.", "My brother is a bully who has to win every discussion.", "People like my boss are simply incapable of listening, and that's just who he is.", "My mother-in-law is hopeless and nothing will ever change her."], nonMatches: ["My coworker is generous and always covers for people, I want to thank her.", "The stubborn stain on my shirt won't come out, any tips?", "The movie's villain was a very dark character but the acting was great.", "My lazy Sunday plan is to read and nap."] },
  { id: "explain_briefly", matches: ["What is a need in this context? I thought needs were just things I want.", "Can you explain what a trigger is, in plain words, before we go on?", "What does projection mean when people use it about arguments?", "Why do I react so strongly when someone criticizes me?", "I keep hearing people say observation versus judgment. Could you break that idea down in plain words?", "Give me the short version of how this whole approach to talking works.", "Sorry, I'm lost on the term empathic listening; a quick definition would help.", "Help me understand the idea that feelings point to something underneath them, in a couple of sentences."], nonMatches: ["What does the weather look like tomorrow in the mountains?", "Can you explain the rules of chess to my kid?", "What is the capital of Australia? I'm doing a quiz tonight.", "What are the needs of a tomato plant? I'm starting a garden."] },
  { id: "guess_then_check", matches: ["I feel really hurt that my friends didn't invite me.", "I'm so frustrated with how things are going at work lately.", "It hurts when my partner brushes off what I say.", "I felt lonely all weekend and I'm not sure why.", "My chest goes tight every time my sister's name appears on my phone and I don't understand it.", "Honestly I'm a mess after the meeting; something in me sank when they gave my project to someone else.", "I'm gutted that nobody remembered my news, and a bit ashamed that it matters so much.", "There's a heavy knot in me lately and I can't name it. Maybe it's about being overlooked?"], nonMatches: ["I feel like pizza tonight, any good toppings?", "I felt the earthquake rumble through the building this morning.", "This sweater makes me feel too warm in the office, can you suggest lighter fabrics?", "The feel of sand between my toes at the beach is my favorite thing about summer."] },
  { id: "deep_fear_refer_out", matches: ["I have panic attacks whenever I have to be around groups and it's gotten worse.", "Since what happened to me years ago, I get flashbacks when someone raises their voice.", "I freeze up completely when my boss talks to me, like my body shuts down.", "I think it's trauma; I can't breathe when I'm near certain people.", "My body goes numb and I lose track of time whenever a certain topic comes up, and it scares me.", "Ever since a bad time in my past, loud arguments make me feel I'm not really there.", "I'm so afraid of other people that leaving the house takes everything I have.", "Certain memories hit me out of nowhere and I'm overwhelmed for hours; I can't cope on my own."], nonMatches: ["My fear of spiders is mild; I just don't like finding them in the shower.", "I'm freezing in this office, can someone turn up the heat?", "The panic buying of toilet paper a few years ago was silly, remember?", "We froze the leftovers last night so they would keep for the week."] },
  { id: "crisis_lines", matches: ["Is there a crisis line I can call tonight? I need to talk to someone.", "Where can I find help? Things at home feel unmanageable.", "Who should I call if I'm overwhelmed and no one I know is around?", "I need to find a therapist near me, how do I start looking?", "Tonight is rough and I'd like to reach a trained listener by phone, preferably free.", "Are there services staffed by real people that I can text when I'm at my limit?", "My friend is in a bad place and I don't know which number to give her for immediate support.", "I think I need counseling but have no idea where people usually begin, or what is affordable."], nonMatches: ["Is there a helpline for my internet provider? My router is dead.", "Where can I find help with my taxes? The deadline is soon.", "Who should I call to fix my leaking kitchen sink?", "The hotel hotline kept me on hold for twenty minutes just to change a booking."] },
  { id: "cnvc", matches: ["Where can I learn nonviolent communication properly, ideally with a teacher?", "Is there a good book on NVC for beginners?", "I'd like a course about compassionate communication; what do you recommend?", "Who is Marshall Rosenberg and where can I read his work?", "Are there workshops or certified trainers who teach this empathic way of speaking?", "I'd love to study this approach in more depth; what organizations offer it?", "My team wants a group session on compassionate dialogue; who runs those?", "Is there a reading list for someone who wants to get better at listening and honest expression?"], nonMatches: ["I need a class for pottery in my city, any recommendations?", "Do you know a good book about gardening for beginners?", "Where can I learn to drive a stick shift this summer?", "Can you recommend a training plan for my first ten kilometer run?"] },
  { id: "podcast", matches: ["Do you know a podcast about communication in relationships?", "I'd like to hear examples of real conversations handled well.", "Is there something I can listen to on my commute about speaking honestly?", "Where can I hear it practiced by real people?", "I learn best by ear. Any audio series where people work through difficult talks?", "Can you recommend something to play while I do dishes that teaches better ways of connecting with people?", "I want to hear what a calm, respectful disagreement sounds like in real life.", "Are there recordings of coaches guiding someone through a tense conversation?"], nonMatches: ["My favorite podcast about baking just released a new episode.", "I want to listen to jazz tonight, any playlists you like?", "Can you hear the echo in my video call? My sound seems odd.", "The radio host said the traffic is terrible on the bridge today."] },
  { id: "offer_a_smaller_step", matches: ["I'm overwhelmed, I can't take in one more thing tonight.", "This is all too much for me right now, I need it to slow down.", "I'm so tired I can't think about this anymore.", "I don't want to go any deeper into this today, I'm full.", "I feel overwhelmed and I'm not sure I can keep talking about it.", "Everything we just went through has left me drained, and I'd rather stop digging for now.", "I need a break from all of this, my head is a fog and nothing is going in.", "Can we leave it here? It is too much to hold at the moment."], nonMatches: ["I'm overwhelmed with joy, my sister just had her baby and I can't stop smiling.", "The view from the top of the hill was overwhelmingly beautiful and we stayed for an hour.", "I'm tired of waiting for the train, it is late again and the platform is freezing.", "That was too much cheese on the pizza, but it was good anyway."] },
  { id: "grieve_before_deciding", matches: ["He told me last night he has lied for a year and I'm devastated, and I'm thinking I should leave him.", "I'm so hurt and furious that I want to divorce my husband tomorrow morning.", "I just found out she cheated and I'm going to break up with her today.", "I'm heartbroken and I'm walking away from my marriage, I can't stay in the same house.", "I can't stop crying and part of me wants to end the friendship right now.", "My best friend betrayed me this morning and I'm going to cut her off for good.", "I'm still shaking from what he said, and I keep asking myself whether I should leave him.", "I was blindsided by what she said and I'm done, I'm calling it quits with my girlfriend."], nonMatches: ["We broke up three years ago and I'm doing really well now, thanks for asking about it.", "I decided to divorce him after two years of counselling and I feel quite at peace about it.", "I'm devastated that my dog died yesterday and I'm just going to take a few days off.", "My friend is getting a divorce and I'd like to help her find a good moving company."] },
  { id: "protective_not_punitive", matches: ["I want him to pay for what he did to me and I don't care how.", "I want her to suffer the way I suffered after what she said.", "I just want him to feel what I felt when he walked out.", "I'm thinking about payback for what they did to my family.", "I want revenge on my old boss for how he treated me.", "He deserves to suffer after everything he put us through.", "I want to get back at her for spreading that story about me.", "I watched my sister cry for a week and I wish he would really pay for it."], nonMatches: ["I want him to pay me back the fifty dollars he owes me from the trip.", "I'm reading a revenge story for book club and it is gripping, any similar ones?", "I want my brother to feel welcome at the party on Saturday.", "I hope they regret nothing and keep going with the project, it looks great."] },
  { id: "rough_draft_first", matches: ["I have to have a hard conversation with my sister tonight and I'm furious with her.", "I need to tell my boss what I think and I'm so angry I'm shaking with rage.", "I'm livid and I'm going to confront my roommate when he gets home.", "I want to talk to my dad, but there is so much anger in me that I can't hold it in.", "There is a difficult talk coming with my landlord and I am absolutely seething.", "I'm going to tell her how I feel, but I'm fuming and I don't trust my own words.", "I have to speak to my coworker tomorrow and I'm so mad I want to scream.", "A big conversation with my partner is tonight and I'm so angry I can barely think straight."], nonMatches: ["I'm furious that my flight was cancelled and the airline won't answer the phone.", "I have a hard conversation with my boss tomorrow and I feel calm and ready for it.", "I need to talk to my landlord about the heating and I'm just going to email him.", "I want to scream at the referee, that call was a disgrace and the whole stadium agrees."] },
  { id: "two_intentions", matches: ["I have to tell my husband something hard and I want him to understand how it felt.", "I'm dreading it, but I need to talk to my mother and I want her to listen for once.", "I'm going to tell my brother something difficult and I want him to stop doing it.", "I want to call out my coworker for this but I'm scared to, and I don't know what I want from it.", "It's awkward, but I have to tell my friend what happened and I want her to see it.", "I need to tell my father something I haven't said in years and I want him to know.", "I need to bring it up with my partner, it's painful, and I want to point it out so it stops.", "I need to talk to him and I'm afraid to, and I don't even know what I want from it."], nonMatches: ["I want to tell my mom happy birthday but her phone is always off, so how should I send it?", "I have to tell my kids dinner is ready and I want them to hurry up before it gets cold.", "I need to talk to my friend about the wedding and I want her to be my maid of honor.", "I'm nervous about the exam on Friday and I want to stop eating junk food while I study."] },
  { id: "name_behavior_neutrally", matches: ["Every time I mention the budget, my husband changes the subject.", "Whenever I raise it, she goes quiet and looks at the wall.", "My boss always interrupts me in meetings, and then moves on to someone else.", "Each time I bring up the chores, he walks out of the room.", "She keeps rolling her eyes whenever I start to talk about my day.", "Every time I ask a question in the team call, my manager sighs.", "My mom usually talks over me at dinner, and I end up not finishing what I started to say.", "Whenever we disagree he checks his phone, and the talk just stops."], nonMatches: ["My cat always walks out of the room when the vacuum starts, it's very dramatic.", "Every time I eat cheese late at night I get a headache and wake up thirsty.", "Whenever it rains the bus is late and I get to work damp.", "The dog keeps interrupting my video calls by barking at the mail carrier."] },
  { id: "smallest_next_step", matches: ["I know what matters to me, I want to finish my novel, and I keep putting it off.", "It matters so much to me and I still haven't started.", "I know exactly what I want to do and I can't seem to start.", "This is really important to me, but I keep avoiding it week after week.", "I care deeply about this and I still haven't made a start.", "I really want to start running again, but I just can't begin, and the days keep going by.", "I know what I need to do, and every day I keep not starting.", "I really want to write to my old teacher and I keep putting it off."], nonMatches: ["I haven't started dinner yet, any quick pasta ideas for tonight?", "I really want pizza tonight, which toppings would go best with olives?", "It is really important to me that you reply by Friday, the form closes then.", "I can't start my car this morning and I think the battery is flat."] },
  { id: "permission_giving", matches: ["I'm sorry for needing so much from you lately.", "Sorry to ask again, I know I'm being a burden.", "I know I shouldn't feel this way about it, but I do.", "Is it selfish to want a weekend just for myself?", "I feel guilty for needing help with the kids.", "I'm sorry I'm so needy, I really don't mean to be.", "I shouldn't even want this, but I can't stop thinking about it.", "Sorry for being so emotional, I just feel everything at once."], nonMatches: ["I'm sorry I yelled at her last night and I want to make it right.", "Sorry for the late reply, I was travelling for work all week.", "I shouldn't have said that to my brother and I regret it.", "My friend said sorry for forgetting and I'm still deciding how I feel."] },
  { id: "ask_one_question", matches: ["I need some advice about my boss.", "Rough day, don't even know where to start.", "Can I get some help with something?", "I just need someone to talk to.", "Hi, I could use some help today.", "Things have been hard lately, honestly.", "I have a problem with my sister.", "Not sure where to begin, to be honest."], nonMatches: ["My manager moved my project to someone else last week without telling me, and I want to ask her why.", "Yesterday my sister and I argued about our mother's care, and I walked out before we finished talking.", "I've been thinking all month about whether to move closer to my parents, and I keep going back and forth.", "After years of working together my business partner stopped answering my calls, and I'm not sure what I did."] },
];
